// Code generated by cmd/breachgen from internal/breach/{rules,cards}.yaml.
// DO NOT EDIT — your change will be overwritten by the next `make breachgen`.
//
// This is the printed rulebook: what the board is, who the characters are, and
// what every card costs and says. It is data, and it is the SAME data the Go
// engine resolves against, which is the entire point of generating it.
//
// What is not here, and never will be: the decision procedure. Nothing in this
// file rolls dice, resolves an attack or decides what a seat may see. Those
// live in internal/breach on the server. The standalone demo interprets the
// data below; it does not carry a second ruleset.

export type Faction = 'red' | 'blue';
export type Owner = Faction | 'neutral';
export type TerritoryKey = 'commons' | 'foundry' | 'marches' | 'outlands' | 'staging';
export type Skill = 'social' | 'tech' | 'opsec' | 'analysis';
export type AbilityKind = 'strike' | 'implant' | 'recon' | 'control' | 'econ' | 'utility';
export type Outcome = 'botch' | 'fail' | 'partial' | 'clean' | 'critical';
export type UpgradeKind = 'roll' | 'ap' | 'quiet' | 'harden';

export interface TerritoryDef {
	key: TerritoryKey;
	name: string;
	real: string;
	color: string;
	glow: string;
	biome: string;
	blurb: string;
	owner: Owner;
}

export interface Structure {
	id: string;
	name: string;
	role: string;
	territory: TerritoryKey;
	owner: Owner;
	piece: string;
	/** The number an attack roll has to beat before anything modifies it. */
	hardening: number;
	/** Blue's standing defences. Shown, not added — already priced into hardening. */
	controls: string[];
	/** 1-based position on the payload path; absent when off the chain. */
	chain?: number;
	note: string;
}

export interface Passive {
	name: string;
	text: string;
}

export interface Klass {
	key: string;
	seat: string;
	name: string;
	faction: Faction;
	color: string;
	icon: string;
	/** The silhouette the renderer draws. No rule reads it. */
	shape: string;
	resource: string;
	skills: Record<Skill, number>;
	tagline: string;
	passive: Passive;
	/** This character's own move. Absent for a class that has none. */
	power?: Power;
}

export interface Upgrade {
	key: string;
	/** The round it comes online. Unlocked, never bought. */
	at: number;
	kind: UpgradeKind;
	value: number;
	name: string;
	icon: string;
	text: string;
}

export interface Ability {
	key: string;
	name: string;
	kind: AbilityKind;
	skill: Skill;
	/** Action points. */
	ap: number;
	/** Roll bonus the card itself brings. */
	mod: number;
	/** Heat added to the target's territory. Failure multiplies it. */
	noise: number;
	/** What the roll is measured against when no building defends. */
	dc?: number;
	targets?: string[];
	on?: Owner[];
	text: string;
}

/**
 * A character's own move.
 *
 * Priced and rolled exactly like a card, and never in a deck — so it cannot be
 * shuffled away from the one person it belongs to. The four of these used to be
 * signature cards, and the discard pile broke that promise.
 */
export interface Power extends Ability {
	/** Charges it starts a match with. Spent, then bought back. */
	uses: number;
}

export interface CardDef {
	ability: Ability;
	/** The klass that contributes it — this decides the card's side. */
	owner: string;
	side: Faction;
	copies: number;
}

/** The last round. Blue survives to it; red has until it to hold the path. */
