export const trackFor = (klassKey: string): Upgrade[] => UPGRADES[klassKey] ?? [];

/** The upgrades online for a seat at a given round. */
export const unlockedFor = (klassKey: string, round: number): Upgrade[] =>
	trackFor(klassKey).filter((u) => round >= u.at);

