export const cardByKey = (key: string): CardDef | undefined =>
	CATALOGUE.find((c) => c.ability.key === key);

export const abilityByKey = (key: string): Ability | undefined => cardByKey(key)?.ability;

/** Every card a side can ever hold. */
export const catalogueFor = (side: Faction): CardDef[] =>
	CATALOGUE.filter((c) => c.side === side);

/** A character's own move, if they have one. */
export const powerOf = (klassKey: string): Power | undefined =>
	ROSTER.find((k) => k.key === klassKey)?.power;

/** The card TYPES a seat can ever hold. Not a hand. */
export const abilitiesOf = (klassKey: string): Ability[] =>
	CATALOGUE.filter((c) => c.owner === klassKey).map((c) => c.ability);
